"""Brute-force solvers for both problems plus tests of the reduction."""

from __future__ import annotations

import itertools
import random

from problems import DominatingSet, Sat
from reduce import reduce


# ---------------------------------------------------------------- solvers
def solve_dominating_set(instance: dict) -> bool:
    """Brute force: try every subset of vertices of size <= k."""
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]

    if k < 0:
        return False
    if n == 0:
        return True
    if k >= n:
        return True

    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for size in range(0, k + 1):
        for chosen in itertools.combinations(range(n), size):
            covered = set(chosen)
            for c in chosen:
                covered |= adj[c]
            if len(covered) == n:
                return True
    return False


def solve_sat(instance: dict) -> bool:
    """DPLL with unit propagation: exact SAT solver."""
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]

    def simplify(clauses, assign):
        # assign: dict var -> bool.  Return (ok, new_clauses).
        new = []
        for clause in clauses:
            satisfied = False
            rest = []
            for lit in clause:
                var = abs(lit)
                if var in assign:
                    val = assign[var] if lit > 0 else not assign[var]
                    if val:
                        satisfied = True
                        break
                else:
                    rest.append(lit)
            if satisfied:
                continue
            if not rest:
                return False, None
            new.append(rest)
        return True, new

    def unit_propagate(clauses, assign):
        while True:
            unit = None
            for clause in clauses:
                if len(clause) == 1:
                    unit = clause[0]
                    break
            if unit is None:
                return True, clauses, assign
            var = abs(unit)
            val = unit > 0
            if var in assign:
                if assign[var] != val:
                    return False, None, None
                # Remove satisfied clause
                clauses = [c for c in clauses if unit not in c]
                continue
            assign = dict(assign)
            assign[var] = val
            ok, clauses = simplify(clauses, {var: val})
            if not ok:
                return False, None, None

    def dpll(clauses, assign):
        ok, clauses, assign = unit_propagate(clauses, assign)
        if not ok:
            return False
        if not clauses:
            return True
        # Choose a variable from the shortest clause.
        shortest = min(clauses, key=len)
        var = abs(shortest[0])
        for val in (True, False):
            ok, sub = simplify(clauses, {var: val})
            if not ok:
                continue
            if dpll(sub, dict(assign, **{var: val})):
                return True
        return False

    return dpll(clauses, {})


# ---------------------------------------------------------------- tests
def all_graphs(n):
    pairs = [(u, v) for u in range(n) for v in range(u + 1, n)]
    for mask in range(1 << len(pairs)):
        edges = [list(pairs[i]) for i in range(len(pairs)) if mask >> i & 1]
        yield {"n": n, "edges": edges}


def check(instance):
    DominatingSet.validate(instance)
    expected = solve_dominating_set(instance)
    target = reduce(instance)
    Sat.validate(target)
    got = solve_sat(target)
    assert expected == got, (instance, target, expected, got)
    return expected


def main():
    tests_run = 0
    tests_passed = 0
    failures = []

    def run(instance):
        nonlocal tests_run, tests_passed
        tests_run += 1
        try:
            check(instance)
            tests_passed += 1
        except AssertionError as exc:
            failures.append(exc)

    # Exhaustive: every graph on 0..4 vertices, every k in -2..n+2.
    for n in range(0, 5):
        for graph in all_graphs(n):
            for k in range(-2, n + 3):
                run({"n": graph["n"], "edges": graph["edges"], "k": k})

    # Random graphs on up to 9 vertices with random k.
    rng = random.Random(12345)
